import re
from typing import Optional
from taf.ul.sc.enb.fzp import Fzp  # type: ignore
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.devices.bts.enb.generic_enb import GenericEnb
from taf.ul.sc.perf.devices.bts.ems import Ems
from taf.ul.sc.syslog import Syslog  # type: ignore
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console


class FzpEnb(GenericEnb):
    def __init__(self,
                 bts: Optional[Fzp] = None,
                 workstation: Optional[UnixFunctionality] = None,
                 api=None,          # not defined yet
                 ems: Optional[Ems] = None,
                 syslog: Optional[Syslog] = None,
                 ):

        super(FzpEnb, self).__init__(bts=bts,
                                     workstation=workstation,
                                     api=api,
                                     ems=ems,
                                     syslog=syslog)

        self.enb_lmp_ip = '192.168.255.129'
        self.dsp_script_params = self._get_dsp_script_params()

    dsp_script = "collect_dsp_stats_FZM.py"

    @property
    def name(self):
        return self.bts.unix.name

    def get_version(self):
        return self.bts.get_version()

    def get_uptime(self, from_file=False):
        return self.bts.unix.get_uptime(from_file=from_file)

    def _get_nid_from_aashel(self):
        self.bts.unix.device.goto_state(state="AASHELL", timeout=10)

        cmd_rad = self.bts.unix.device.get_cmd(cmd_name="rad", cmd_params={"options": "-nsr AaSysLogSicAddressLocal"})
        rad = cmd_rad()

        nid = '123D'
        if rad['RESULT'] is not {}:
            key = list(rad['RESULT'].keys())[0]
            result = rad['RESULT'][key]
            regex = re.compile(r'0x([\d\w]{4})')
            nid = regex.search(str(result['value'])).group(1)

        self.bts.unix.device.goto_state(state="LINUX")
        return nid

    def _get_dsp_script_params(self):
        nid = self._get_nid_from_aashel()
        return [nid, self.enb_lmp_ip]

    @log_function_status_to_console(msg="Collect snapshot", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_snapshot(self, log_dir):
        self.bts.get_aashel_snapshot(local_dir=log_dir)

    @log_function_status_to_console(msg="Collect additional logs", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_additional_logs(self, log_dir):
        self.bts.get_journal_files(local_dir=log_dir)
        self.bts.get_raw_alarm_history(local_dir=log_dir)

    @log_function_status_to_console(msg="Collect configuration", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def collect_configuration(self, log_dir):
        self.bts.get_enb_config(local_dir=log_dir)
        self._collect_swconfig(log_dir)

    @log_function_status_to_console(msg="Start Benchmark stats collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_benchmark_stats_collecting(self, period=None):
        self._start_benchmark_stats_collecting(device=self.bts.unix, period=period)

    @log_function_status_to_console(msg="Stop Benchmark stats collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_benchmark_stats_collecting(self):
        self._stop_benchmark_stats_collecting(device=self.bts.unix)

    @log_function_status_to_console(msg="Start DSP collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def start_dsp_stats_collecting(self):
        self._start_dsp_stats_collecting(workstation=self.ws, dsp_script=self.dsp_script,
                                         script_params=self.dsp_script_params)

    @log_function_status_to_console(msg="Stop DSP collecting", log_hierarchy=2, add_name_prefix=True)
    @log_debug_function_info()
    def stop_dsp_stats_collecting(self):
        self._stop_dsp_stats_collecting(workstation=self.ws, dsp_script=self.dsp_script,
                                        script_params=self.dsp_script_params)
